/**
 * Photography. All images are free-licence stock photos from Pexels (https://www.pexels.com/license/), chosen to show
 * logistics, customs paperwork, teams and office work without implying services Staffing Wise does not provide.
 * They are illustrative, not photos of Staffing Wise staff or clients. Sources are listed in docs/image-credits.md.
 *
 * Files live in public/images (max 2400px; next/image serves resized AVIF/WebP). Dimensions and blur placeholders come
 * from image-manifest.json, generated by `npm run images:manifest`. Add a new photo with `npm run images:add`.
 */
import manifest from "./image-manifest.json";

export type Photo = {
  src: string;
  alt: string;
  width: number;
  height: number;
  blurDataURL: string;
  /** CSS object-position for cropped (object-cover) layouts: keeps the subject in frame at every breakpoint. */
  position?: string;
};

type ManifestKey = keyof typeof manifest;

const photo = (file: ManifestKey, alt: string, position?: string): Photo => {
  const meta = manifest[file];
  return { src: `/images/${file}.jpg`, alt, width: meta.width, height: meta.height, blurDataURL: meta.blurDataURL, position };
};

