/**
 * Common props for a next/image with this photo: blur placeholder while loading and the focal point when cropped.
 * Pass alt explicitly: alt={photo.alt}, or alt="" when the image is decorative (for example beside a text link with the same meaning).
 */
export function photoProps(p: Photo) {
  return {
    src: p.src,
    placeholder: "blur" as const,
    blurDataURL: p.blurDataURL,
    style: p.position ? { objectPosition: p.position } : undefined,
  };
}
